window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d0fe277d9cf655d7"]={"versions": [{"id": "FIG-d0fe277d9cf655d7", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Kollaborations- und Datenflussdiagramm mit Swimlanes (Partitionen) im Kontext des modellbasierten Datenaustauschs und Werkzeug-Interoperabilität nach AUTOSAR TR Interoperability of AUTOSAR Tools. Das Diagramm illustriert das Problem der nebenläufigen Modellierung (Concurrent Modeling) beim Umbenennen von Modellelementen zwischen zwei kooperierenden Parteien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Swimlanes / Domänen</strong>: Zwei horizontale Partitionen für <code>party X</code> (obere Partition) und <code>Party Y</code> (untere Partition).</li>\n<li><strong>Pakete / Modell-Container</strong>:</li>\n<li><code>Model B</code>: Lokales Modell von Party X, enthält die Instanz bzw. das Element <code>X</code>.</li>\n<li><code>Model A [source]</code>: Ausgangsmodell bei Party X, enthält das Element <code>BrakControl[source]</code>.</li>\n<li><code>Model A [remote]</code>: Zu Party Y transferiertes Modell, enthält das Element <code>BrakControl [remote]</code>.</li>\n<li><code>Model A [merged]</code>: Bei Party Y bearbeitetes Modell, enthält das umbenannte Element <code>BrakeControl [merged]</code>.</li>\n<li><code>Model A [updated]</code>: An Party X zurückübertragenes Modell, enthält das Element <code>BrakeControl [updated]</code>.</li>\n<li><strong>Aktivitäten / Operationen</strong>:</li>\n<li><code>Rename</code>: Abgerundeter Aktionsblock innerhalb von Party Y, der die Umbenennung repräsentiert.</li>\n<li><strong>Beziehungen & Relationen</strong>:</li>\n<li>Assoziation (durchgezogene Linie) zwischen Element <code>X</code> in <code>Model B</code> und Element <code>BrakControl[source]</code> in <code>Model A [source]</code>.</li>\n<li>Gestrichelte Abhängigkeiten mit Stereotyp <code>«trace»</code> für den Modelltransfer zwischen Party X und Party Y.</li>\n<li>Gestrichelte Kontroll-/Datenfluss-Pfeile von <code>Model A [remote]</code> über die Aktion <code>Rename</code> zu <code>Model A [merged]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Ausgangszustand bei Party X</strong>: Element <code>X</code> aus <code>Model B</code> referenziert das Modellelement <code>BrakControl[source]</code> in <code>Model A [source]</code>.</li>\n<li><strong>Export / Übergabe</strong>: <code>Model A [source]</code> wird an Party Y übergeben (dargestellt über den gerichteten <code>«trace»</code>-Pfeil von Party X zu <code>Model A [remote]</code> in Party Y).</li>\n<li><strong>Modifikation bei Party Y</strong>: Party Y führt die Aktion <code>Rename</code> aus; <code>BrakControl [remote]</code> wird zu <code>BrakeControl [merged]</code> umbenannt und liegt in <code>Model A [merged]</code> vor.</li>\n<li><strong>Rückführung / Re-Import</strong>: <code>Model A [merged]</code> wird zurück zu Party X übertragen (gerichteter <code>«trace»</code>-Pfeil auf <code>Model A [updated]</code>).</li>\n<li><strong>Konfliktsituation bei Merge</strong>: Party X muss <code>Model A [updated]</code> mit dem lokalen Datenbestand zusammenführen; die ursprüngliche Referenz von <code>X</code> auf <code>BrakControl</code> läuft ins Leere bzw. kann ohne eindeutige Identifikatoren nicht automatisch auf <code>BrakeControl</code> migriert werden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt informativen Charakter zur Veranschaulichung der Modell-Interoperabilität und Verdeutlichung der Grenzen rein namensbasierter Elementidentifikation bei paralleler Bearbeitung (<code>atpSplitable</code> / modellübergreifende Assoziationen). Für Werkzeugentwickler resultiert die Notwendigkeit robuster Identifikations- und Verfolgungsmechanismen (z. B. persistente UUIDs/GIDs anstelle reiner Kurznamen <code>shortName</code>), um bei Umbenennungen die Referenzintegrität (<code>Model B</code> -> <code>BrakeControl</code>) beim Re-Import sicherzustellen.</p>"}, {"id": "FIG-69b4005b8c7c4446", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Kollaborations- und Datenflussdiagramm mit Swimlanes (Partitionen) im Kontext des modellbasierten Datenaustauschs und Werkzeug-Interoperabilität nach AUTOSAR TR Interoperability of AUTOSAR Tools. Das Diagramm illustriert das Problem der nebenläufigen Modellierung (Concurrent Modeling) beim Umbenennen von Modellelementen zwischen zwei kooperierenden Parteien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Swimlanes / Domänen</strong>: Zwei horizontale Partitionen für <code>party X</code> (obere Partition) und <code>Party Y</code> (untere Partition).</li>\n<li><strong>Pakete / Modell-Container</strong>:</li>\n<li><code>Model B</code>: Lokales Modell von Party X, enthält die Instanz bzw. das Element <code>X</code>.</li>\n<li><code>Model A [source]</code>: Ausgangsmodell bei Party X, enthält das Element <code>BrakControl[source]</code>.</li>\n<li><code>Model A [remote]</code>: Zu Party Y transferiertes Modell, enthält das Element <code>BrakControl [remote]</code>.</li>\n<li><code>Model A [merged]</code>: Bei Party Y bearbeitetes Modell, enthält das umbenannte Element <code>BrakeControl [merged]</code>.</li>\n<li><code>Model A [updated]</code>: An Party X zurückübertragenes Modell, enthält das Element <code>BrakeControl [updated]</code>.</li>\n<li><strong>Aktivitäten / Operationen</strong>:</li>\n<li><code>Rename</code>: Abgerundeter Aktionsblock innerhalb von Party Y, der die Umbenennung repräsentiert.</li>\n<li><strong>Beziehungen & Relationen</strong>:</li>\n<li>Assoziation (durchgezogene Linie) zwischen Element <code>X</code> in <code>Model B</code> und Element <code>BrakControl[source]</code> in <code>Model A [source]</code>.</li>\n<li>Gestrichelte Abhängigkeiten mit Stereotyp <code>«trace»</code> für den Modelltransfer zwischen Party X und Party Y.</li>\n<li>Gestrichelte Kontroll-/Datenfluss-Pfeile von <code>Model A [remote]</code> über die Aktion <code>Rename</code> zu <code>Model A [merged]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Ausgangszustand bei Party X</strong>: Element <code>X</code> aus <code>Model B</code> referenziert das Modellelement <code>BrakControl[source]</code> in <code>Model A [source]</code>.</li>\n<li><strong>Export / Übergabe</strong>: <code>Model A [source]</code> wird an Party Y übergeben (dargestellt über den gerichteten <code>«trace»</code>-Pfeil von Party X zu <code>Model A [remote]</code> in Party Y).</li>\n<li><strong>Modifikation bei Party Y</strong>: Party Y führt die Aktion <code>Rename</code> aus; <code>BrakControl [remote]</code> wird zu <code>BrakeControl [merged]</code> umbenannt und liegt in <code>Model A [merged]</code> vor.</li>\n<li><strong>Rückführung / Re-Import</strong>: <code>Model A [merged]</code> wird zurück zu Party X übertragen (gerichteter <code>«trace»</code>-Pfeil auf <code>Model A [updated]</code>).</li>\n<li><strong>Konfliktsituation bei Merge</strong>: Party X muss <code>Model A [updated]</code> mit dem lokalen Datenbestand zusammenführen; die ursprüngliche Referenz von <code>X</code> auf <code>BrakControl</code> läuft ins Leere bzw. kann ohne eindeutige Identifikatoren nicht automatisch auf <code>BrakeControl</code> migriert werden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt informativen Charakter zur Veranschaulichung der Modell-Interoperabilität und Verdeutlichung der Grenzen rein namensbasierter Elementidentifikation bei paralleler Bearbeitung (<code>atpSplitable</code> / modellübergreifende Assoziationen). Für Werkzeugentwickler resultiert die Notwendigkeit robuster Identifikations- und Verfolgungsmechanismen (z. B. persistente UUIDs/GIDs anstelle reiner Kurznamen <code>shortName</code>), um bei Umbenennungen die Referenzintegrität (<code>Model B</code> -> <code>BrakeControl</code>) beim Re-Import sicherzustellen.</p>"}], "trans": [{"from": "FIG-d0fe277d9cf655d7", "to": "FIG-69b4005b8c7c4446", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
